import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, API_BASE, WEB_BASE } from '../auth.helpers'

// ── US1: Admin creates a board and adds lanes ─────────────────────────────────

test.describe('US1: Admin creates a board and adds lanes', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — admin creates a board and is assigned Owner role', async ({ page }) => {
    const boardName = `Scenario 1 Board ${Date.now()}`

    await page.goto(`${WEB_BASE}/`)
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible()

    await page.getByRole('button', { name: /create board/i }).click()
    const nameInput = page.getByRole('textbox', { name: /board name/i })
    await nameInput.fill(boardName)
    await page.getByRole('button', { name: /^create$/i }).click()

    await expect(page).toHaveURL(/\/boards\/[0-9a-f-]+/, { timeout: 10_000 })
    await expect(page.getByRole('heading', { level: 1, name: boardName })).toBeVisible({ timeout: 30_000 })
  })

  test('scenario 2 — admin adds three lanes and they appear in insertion order', async ({
    page,
    request,
  }) => {
    const boardName = `Lane Order Board ${Date.now()}`
    const createResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: boardName },
    })
    expect(createResp.ok()).toBeTruthy()
    const board = await createResp.json()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible({ timeout: 10_000 })

    for (const laneName of ['To Do', 'In Progress', 'Done']) {
      await page.getByRole('button', { name: /add lane/i }).click()
      await page.getByRole('textbox', { name: /lane name/i }).fill(laneName)
      await page.getByRole('button', { name: /^add$/i }).click()
      await expect(page.getByRole('heading', { name: laneName })).toBeVisible()
    }

    const lanes = page.getByRole('region', { name: /lane/i })
    await expect(lanes.nth(0)).toContainText('To Do')
    await expect(lanes.nth(1)).toContainText('In Progress')
    await expect(lanes.nth(2)).toContainText('Done')
  })

  test('scenario 3 — board list shows the newly created board', async ({ page, request }) => {
    const boardName = `Listed Board ${Date.now()}`
    await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })

    await page.goto(`${WEB_BASE}/`)
    await expect(page.getByText(boardName)).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 4 — duplicate board name is rejected with conflict error', async ({
    page,
    request,
  }) => {
    const boardName = `Duplicate Board ${Date.now()}`
    await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })

    await page.goto(`${WEB_BASE}/`)
    await page.getByRole('button', { name: /create board/i }).click()
    await page.getByRole('textbox', { name: /board name/i }).fill(boardName)
    await page.getByRole('button', { name: /^create$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 5 — duplicate lane name within a board is rejected', async ({
    page,
    request,
  }) => {
    const boardName = `Dup Lane Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: boardName },
    })
    const board = await boardResp.json()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible({ timeout: 10_000 })
    await page.getByRole('button', { name: /add lane/i }).click()
    await page.getByRole('textbox', { name: /lane name/i }).fill('Backlog')
    await page.getByRole('button', { name: /^add$/i }).click()
    await expect(page.getByRole('heading', { name: 'Backlog' })).toBeVisible()

    await page.getByRole('button', { name: /add lane/i }).click()
    await page.getByRole('textbox', { name: /lane name/i }).fill('Backlog')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })
})

// ── US1: Non-admin cannot create boards ──────────────────────────────────────

test.describe('US1: Non-admin user cannot create boards', () => {
  test('scenario 6 — non-admin sees no create board button', async ({ browser }) => {
    const uniqueEmail = `member-${Date.now()}@example.com`
    const ctx = await browser.newContext()
    const page = await ctx.newPage()

    await page.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(uniqueEmail)}&displayName=Member+User`,
    )
    await page.waitForURL(`${WEB_BASE}/**`)

    await page.goto(`${WEB_BASE}/`)

    await expect(page.getByRole('button', { name: /create board/i })).not.toBeVisible()

    await ctx.close()
  })
})

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter } from 'react-router-dom'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import './index.css'
import App from './App.tsx'

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 30_000,
      retry: (failureCount, error) => {
        const status = (error as { status?: number }).status
        if (status !== undefined && status >= 400 && status < 500) return false
        return failureCount < 2
      },
    },
    mutations: {
      retry: false,
    },
  },
})

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <BrowserRouter>
      <QueryClientProvider client={queryClient}>
        <App />
        {import.meta.env.DEV && <ReactQueryDevtools initialIsOpen={false} />}
      </QueryClientProvider>
    </BrowserRouter>
  </StrictMode>
)

import { useState } from 'react'
import { Button, Title2, makeStyles, tokens } from '@fluentui/react-components'
import type { Card, Lane as LaneData } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'
import CardItem from './CardItem'
import AddCardForm from './AddCardForm'
import CardDetailDialog from './CardDetailDialog'

const useStyles = makeStyles({
  lane: {
    minWidth: '260px',
    maxWidth: '320px',
    backgroundColor: tokens.colorNeutralBackground2,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalM,
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cards: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  emptySlot: {
    height: '40px',
    borderRadius: tokens.borderRadiusMedium,
    border: `1px dashed ${tokens.colorNeutralStroke2}`,
  },
})

interface LaneProps {
  lane: LaneData
  callerRole: BoardRole
  onDelete: (boardId: string, laneId: string) => void
}

export default function Lane({ lane, callerRole, onDelete }: LaneProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'
  const [editingCard, setEditingCard] = useState<Card | null>(null)
  const [editDialogOpen, setEditDialogOpen] = useState(false)
  const [deletingCard, setDeletingCard] = useState<Card | null>(null)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)

  const sortedCards = [...lane.cards].sort((a, b) => a.position - b.position)

  const openEdit = (card: Card) => {
    setEditingCard(card)
    setEditDialogOpen(true)
  }

  const openDelete = (card: Card) => {
    setDeletingCard(card)
    setDeleteDialogOpen(true)
  }

  return (
    <section className={styles.lane} aria-label={`Lane: ${lane.name}`}>
      <div className={styles.header}>
        <Title2 as="h2">{lane.name}</Title2>
        {canModify && (
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete lane ${lane.name}`}
            onClick={() => onDelete(lane.boardId, lane.id)}
          >
            Delete
          </Button>
        )}
      </div>
      <div className={styles.cards}>
        {sortedCards.length === 0 && !canModify && (
          <div className={styles.emptySlot} aria-hidden="true" />
        )}
        {sortedCards.map((card) => (
          <CardItem
            key={card.id}
            card={card}
            callerRole={callerRole}
            onEdit={openEdit}
            onDelete={openDelete}
          />
        ))}
      </div>
      {canModify && <AddCardForm boardId={lane.boardId} laneId={lane.id} />}
      {editingCard && (
        <CardDetailDialog
          key={editingCard.id}
          card={editingCard}
          open={editDialogOpen}
          onClose={() => setEditDialogOpen(false)}
        />
      )}
      {deletingCard && (
        <CardDetailDialog
          key={`delete-${deletingCard.id}`}
          card={deletingCard}
          open={deleteDialogOpen}
          onClose={() => setDeleteDialogOpen(false)}
          initialConfirmDelete={true}
        />
      )}
    </section>
  )
}

using System.Data;
using System.Security.Claims;
using Dapper;
using FluentValidation;
using FluentValidation.Results;
using Kanban.Api.Options;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain.Enums;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.Extensions.Options;

namespace Kanban.Api.Endpoints;

// Dev-only test infrastructure — architecture boundary exception.
// Direct DataAccess and Domain usage is intentional here; this file is
// never registered outside IsDevelopment() and must not ship to production.
internal static class DevEndpoints
{
    internal static void Map(IEndpointRouteBuilder routes)
    {
        routes.MapGet("/dev/authenticate",
            async (
                string email,
                string? displayName,
                IUserRepository userRepository,
                IOptions<CorsOptions> corsOptions,
                HttpContext ctx) =>
            {
                var user = await userRepository.FindByEmailAsync(email);

                List<Claim> claims;
                if (user is not null)
                {
                    claims =
                    [
                        new Claim("sub", user.GoogleSub ?? $"dev-sub-{email}"),
                        new Claim("email", user.Email),
                        new Claim("name", user.DisplayName),
                        new Claim("user_id", user.Id.ToString()),
                        new Claim("system_role",
                            user.SystemRole == SystemRole.Admin ? "admin" : "standard"),
                    ];
                }
                else
                {
                    claims =
                    [
                        new Claim("sub", $"dev-sub-{email}"),
                        new Claim("email", email),
                        new Claim("name", displayName ?? email),
                    ];
                }

                var identity = new ClaimsIdentity(
                    claims, CookieAuthenticationDefaults.AuthenticationScheme);
                await ctx.SignInAsync(
                    CookieAuthenticationDefaults.AuthenticationScheme,
                    new ClaimsPrincipal(identity));

                var frontendOrigin = corsOptions.Value.AllowedOrigins.FirstOrDefault()
                    ?? "http://localhost:5173";
                return Results.Redirect(frontendOrigin);
            })
            .WithName("DevAuthenticate")
            .WithSummary("[DEV ONLY] Issue an auth cookie without Google OAuth — Playwright use only")
            .AllowAnonymous();

        routes.MapPost("/dev/seed/invitation",
            async (
                DevSeedInvitationRequest request,
                IDbConnection db) =>
            {
                var adminId = await db.QuerySingleOrDefaultAsync<string>(
                    "SELECT id FROM users WHERE system_role = 'Admin' LIMIT 1");

                if (adminId is null)
                    return Results.NotFound("No admin user found in database");

                var (rawToken, tokenHash) = GenerateToken();
                var now = DateTimeOffset.UtcNow;
                var expiresAt = now.AddDays(request.ExpiresInDays ?? 7);
                var consumedAt = request.Consumed ? now.AddMinutes(-1) : (DateTimeOffset?)null;

                await db.ExecuteAsync(
                    """
                    INSERT INTO invitations
                        (id, email, issued_by_user_id, token_hash, issued_at, expires_at, consumed_at, consumed_by_user_id)
                    VALUES (@id, @email, @issuedByUserId, @tokenHash, @issuedAt, @expiresAt, @consumedAt, NULL)
                    """,
                    new
                    {
                        id = Guid.NewGuid().ToString("D"),
                        email = request.Email,
                        issuedByUserId = adminId,
                        tokenHash,
                        issuedAt = now.ToString("o"),
                        expiresAt = expiresAt.ToString("o"),
                        consumedAt = consumedAt?.ToString("o"),
                    });

                return Results.Ok(new { token = rawToken });
            })
            .WithName("DevSeedInvitation")
            .WithSummary("[DEV ONLY] Seed an invitation record for Playwright testing")
            .AllowAnonymous();

        routes.MapPost("/dev/seed-board-member",
            async (
                DevSeedBoardMemberRequest request,
                IDbConnection db) =>
            {
                var validRoles = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "Owner", "Member", "Viewer" };
                if (!validRoles.Contains(request.Role))
                    return Results.BadRequest($"Invalid role '{request.Role}'. Must be Owner, Member, or Viewer.");

                var now = DateTimeOffset.UtcNow;
                await db.ExecuteAsync(
                    """
                    INSERT OR IGNORE INTO users (id, google_sub, email, display_name, system_role, registered_at)
                    VALUES (@id, @sub, @email, @displayName, 'Standard', @createdAt)
                    """,
                    new
                    {
                        id = Guid.NewGuid().ToString("D"),
                        sub = $"dev-sub-{request.Email}",
                        email = request.Email,
                        displayName = request.Email,
                        createdAt = now.ToString("o"),
                    });

                var userId = await db.QuerySingleAsync<string>(
                    "SELECT id FROM users WHERE email = @email",
                    new { email = request.Email });

                var adminId = await db.QuerySingleOrDefaultAsync<string>(
                    "SELECT id FROM users WHERE system_role = 'Admin' LIMIT 1");
                if (adminId is null)
                    return Results.NotFound("No admin user found in database");

                var memberId = Guid.NewGuid();
                await db.ExecuteAsync(
                    """
                    INSERT OR IGNORE INTO board_members (id, board_id, user_id, role, invited_by_user_id, joined_at)
                    VALUES (@id, @boardId, @userId, @role, @invitedBy, @joinedAt)
                    """,
                    new
                    {
                        id = memberId.ToString("D"),
                        boardId = request.BoardId.ToString("D"),
                        userId = userId,
                        role = request.Role,
                        invitedBy = adminId,
                        joinedAt = now.ToString("o"),
                    });

                return Results.Ok(new { userId = Guid.Parse(userId) });
            })
            .WithName("DevSeedBoardMember")
            .WithSummary("[DEV ONLY] Seed a user and board membership — Playwright use only")
            .AllowAnonymous();

        routes.MapGet("/dev/test/throw-validation", () =>
            {
                var failures = new[] { new ValidationFailure("TestField", "Must not be empty") };
                throw new ValidationException("Validation failed", failures);
#pragma warning disable CS0162
                return Results.Ok();
#pragma warning restore CS0162
            })
            .WithName("DevTestThrowValidation")
            .WithSummary("[DEV ONLY] Throw ValidationException — error handler mapping test only")
            .AllowAnonymous();
    }

    private static (string rawToken, string tokenHash) GenerateToken()
    {
        var bytes = System.Security.Cryptography.RandomNumberGenerator.GetBytes(32);
        var raw = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        var hash = Convert.ToHexString(
            System.Security.Cryptography.SHA256.HashData(
                System.Text.Encoding.UTF8.GetBytes(raw))).ToLower();
        return (raw, hash);
    }
}

internal sealed record DevSeedInvitationRequest(
    string Email,
    double? ExpiresInDays = null,
    bool Consumed = false);

internal sealed record DevSeedBoardMemberRequest(
    string Email,
    Guid BoardId,
    string Role);
